import pandas as pd

def clean(df):
    df = df.copy()
    if 'island' in df.columns:
        df['island'] = df['island'].str.strip()
    if 'species' in df.columns:
        df['species'] = df['species'].replace({'chinstrap': 'Chinstrap'})
    return df

def answer(df):
    df = clean(df)
    counts = df['island'].value_counts().to_dict()
    return counts
